def solve(grid):
    if not grid: return 0
    rows,cols=len(grid),len(grid[0]); seen=set(); count=0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]!=1 or (r,c) in seen: continue
            count+=1; seen.add((r,c)); stack=[(r,c)]
            while stack:
                x,y=stack.pop()
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<rows and 0<=b<cols and grid[a][b]==1 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
    return count
